{
  "topic": "导数与极限",
  "language": "中文",
  "concepts": [
    {
      "name": "导数",
      "category": "核心概念",
      "related_concepts": ["变化率", "极限", "瞬时变化率"],
      "definition_snippet": "函数在某一点处变化快慢的瞬时度量，需通过极限严格定义。"
    },
    {
      "name": "变化率",
      "category": "核心概念",
      "related_concepts": ["导数", "瞬时变化率", "平均变化率"],
      "definition_snippet": "描述函数值随自变量变化而变化快慢程度的量。"
    },
    {
      "name": "极限",
      "category": "核心概念",
      "related_concepts": ["导数", "逼近", "无穷小"],
      "definition_snippet": "描述变量在无限逼近某状态时所趋向的确定数值，是微积分的严格基础。"
    },
    {
      "name": "瞬时变化率",
      "category": "核心概念",
      "related_concepts": ["导数", "变化率", "切线斜率"],
      "definition_snippet": "函数在某一特定时刻或某一点处的精确变化速度。"
    },
    {
      "name": "平均变化率",
      "category": "相关概念",
      "related_concepts": ["变化率", "差商", "割线斜率"],
      "definition_snippet": "函数在某一区间内单位自变量增量对应的平均函数值变化量。"
    },
    {
      "name": "函数",
      "category": "相关概念",
      "related_concepts": ["自变量", "因变量", "连续性"],
      "definition_snippet": "描述两个变量之间对应关系的数学模型，是导数的研究对象。"
    },
    {
      "name": "差商",
      "category": "相关概念",
      "related_concepts": ["平均变化率", "极限", "导数"],
      "definition_snippet": "函数增量与自变量增量之比，其极限即为导数。"
    },
    {
      "name": "逼近",
      "category": "相关概念",
      "related_concepts": ["极限", "无穷小", "割线斜率"],
      "definition_snippet": "通过让自变量增量趋于零，使近似值无限接近精确值的思想方法。"
    },
    {
      "name": "无穷小",
      "category": "相关概念",
      "related_concepts": ["极限", "逼近", "连续性"],
      "definition_snippet": "以零为极限的变量，用于刻画无限趋近过程中的微小增量。"
    },
    {
      "name": "连续性",
      "category": "相关概念",
      "related_concepts": ["极限", "函数", "导数"],
      "definition_snippet": "函数在某点极限值等于函数值且图像无间断的性质，是可导的前提之一。"
    },
    {
      "name": "切线斜率",
      "category": "具体事例",
      "related_concepts": ["导数", "瞬时变化率", "割线斜率"],
      "definition_snippet": "函数图像在某一点切线的倾斜程度，其数值等于该点导数。"
    },
    {
      "name": "割线斜率",
      "category": "具体事例",
      "related_concepts": ["平均变化率", "切线斜率", "差商"],
      "definition_snippet": "连接函数图像上两点的割线斜率，表示区间内的平均变化率。"
    }
  ],
