    },
    {
      "name": "不定积分",
      "category": "核心概念",
      "related_concepts": ["原函数", "积分", "微分"],
      "definition_snippet": "求一个函数全体原函数的运算，结果含任意常数。"
    },
    {
      "name": "定积分",
      "category": "核心概念",
      "related_concepts": ["面积", "积分", "极限"],
      "definition_snippet": "在区间上对函数求和取极限，用于精确计算面积与总量。"
    },
    {
      "name": "微分",
      "category": "相关概念",
      "related_concepts": ["导数", "函数", "极限"],
      "definition_snippet": "用导数线性近似描述函数微小增量的运算。"
    },
    {
      "name": "函数",
      "category": "相关概念",
      "related_concepts": ["导数", "积分", "极限"],
      "definition_snippet": "将自变量与因变量按对应关系联系起来的数学对象。"
    },
    {
      "name": "极限",
      "category": "相关概念",
      "related_concepts": ["微积分", "导数", "定积分"],
      "definition_snippet": "描述变量无限趋近某一状态时函数变化趋势的基础概念。"
    },
    {
      "name": "曲线",
      "category": "具体事例",
      "related_concepts": ["面积", "函数", "定积分"],
      "definition_snippet": "函数图像形成的连续线条，其围成区域面积可用积分求解。"
