{
  "topic": "导数",
  "language": "de",
  "concepts": [
    {
      "name": "Ableitung",
      "category": "核心概念",
      "related_concepts": ["Änderungsrate", "Funktion", "Grenzwert"],
      "definition_snippet": "函数在某一点的瞬时变化率，用于刻画函数值随自变量变化的快慢。"
    },
    {
      "name": "Änderungsrate",
      "category": "核心概念",
      "related_concepts": ["Ableitung", "Steigung", "Differenzenquotient"],
      "definition_snippet": "描述一个量相对于另一个量变化快慢程度的度量，导数即为瞬时变化率。"
    },
    {
      "name": "Funktion",
      "category": "核心概念",
      "related_concepts": ["Ableitung", "Variable", "Punkt"],
      "definition_snippet": "将定义域中每个自变量值唯一映射到一个因变量值的对应关系。"
    },
    {
      "name": "Punkt",
      "category": "相关概念",
      "related_concepts": ["Funktion", "Ableitung", "Tangente"],
      "definition_snippet": "函数定义域或图像上的特定位置，导数即定义在该点处的局部性质。"
    },
    {
      "name": "Steigung",
      "category": "相关概念",
      "related_concepts": ["Ableitung", "Tangente", "Änderungsrate"],
      "definition_snippet": "曲线或直线倾斜程度的数值表示，导数在几何上即为切线的斜率。"
    },
    {
      "name": "Tangente",
      "category": "相关概念",
      "related_concepts": ["Steigung", "Punkt", "Grenzwert"],
      "definition_snippet": "在某点与曲线仅有一个局部交点且方向一致的直线，其斜率等于该点导数。"
    },
    {
      "name": "Grenzwert",
      "category": "核心概念",
      "related_concepts": ["Ableitung", "Differenzenquotient", "Differentialquotient"],
      "definition_snippet": "当自变量趋近某值时函数值所趋向的极限，是定义导数的基础工具。"
    },
    {
      "name": "Differenzenquotient",
      "category": "相关概念",
      "related_concepts": ["Grenzwert", "Änderungsrate", "Differentialquotient"],
      "definition_snippet": "函数在两点间平均变化率的比值，即 Δy/Δx，用于逼近导数。"
    },
    {
      "name": "Differentialquotient",
      "category": "相关概念",
      "related_concepts": ["Differenzenquotient", "Grenzwert", "Ableitung"],
      "definition_snippet": "差商在区间趋于零时的极限值，即导数的极限定义形式。"
    },
    {
      "name": "Differentialrechnung",
      "category": "相关概念",
      "related_concepts": ["Ableitung", "Funktion", "Stetigkeit"],
      "definition_snippet": "以导数和微分为核心研究函数变化规律的微积分分支。"
    },
    {
      "name": "Stetigkeit",
      "category": "相关概念",
      "related_concepts": ["Funktion", "Grenzwert", "Ableitung"],
      "definition_snippet": "函数在某点极限值等于函数值的性质，可导必连续但连续不一定可导。"
    },
    {
      "name": "Variable",
      "category": "相关概念",
      "related_concepts": ["Funktion", "Punkt", "Änderungsrate"],
      "definition_snippet": "函数中可取不同数值的自变量或因变量，是描述变化关系的基本要素。"
